# python
from openpyxl import load_workbook
from openpyxl.utils import column_index_from_string

file_path = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx'
wb = load_workbook(file_path)
ws = wb.active

max_row = ws.max_row
max_col = ws.max_column

map_data = {}
blue_cells = []

def rgb6(argb):
    if not argb:
        return None
    return argb[-6:].upper()

def is_blue(hex6):
    if not hex6:
        return False
    r = int(hex6[0:2], 16)
    g = int(hex6[2:4], 16)
    b = int(hex6[4:6], 16)
    return b > 200 and r < 50 and g < 180

for row in ws.iter_rows():
    for cell in row:
        coord = cell.coordinate
        val = cell.value
        fill = cell.fill
        color = None
        try:
            if fill and fill.fgColor and fill.fgColor.type == 'rgb' and fill.fgColor.rgb:
                color = rgb6(fill.fgColor.rgb)
        except Exception:
            color = None
        map_data[coord] = {'value': val, 'color': color}
        if is_blue(color):
            blue_cells.append(coord)

print('Map size:', max_row, 'rows x', max_col, 'cols')
print('Blue count:', len(blue_cells))
print('Sample:', list(map_data.items())[:10])
