from openpyxl.utils import column_index_from_string

def coord_to_indices(coord):
    # e.g., A1 -> (1,1)
    for i, ch in enumerate(coord):
        if ch.isdigit():
            col = column_index_from_string(coord[:i])
            row = int(coord[i:])
            return (row, col)
    return None

cell_map = {}
blue_indices = set()
for coord, info in map_data.items():
    rc = coord_to_indices(coord)
    cell_map[rc] = {'value': info['value'], 'color': info['color']}
    if coord in blue_cells:
        blue_indices.add(rc)

print('Cell (1,1):', cell_map.get((1,1)))
print('Blue sample idx:', list(blue_indices)[:5])
